+
+    @Override
+    protected NodeInfo<Values> info() {
+        return NodeInfo.create(this, Values::new, field());
+    }
+
+    @Override
+    public Values replaceChildren(List<Expression> newChildren) {
+        return new Values(source(), newChildren.get(0));
