+                    nestedDepth++;
+
+                    if (nestedDepth > 2) {
+                        throw new IllegalArgumentException(
+                            "the nested depth of the [" + name + "] retriever exceeds the maximum nested depth [2] for retrievers"
+                        );
+                    }
