+        return vec;
+    }
+
+    public float[] asFloatVector() {
+        if (floatVector != null) {
+            return floatVector;
+        }
+        float[] vec = new float[byteVector.length];
+        for (int i = 0; i < byteVector.length; i++) {
+            vec[i] = byteVector[i];
+        }
+        return vec;
+    }
+
+    public void addToBuffer(ByteBuffer byteBuffer) {
+        if (floatVector != null) {
+            for (float val : floatVector) {
